from boltons.setutils import IndexedSet

def check(n, ops, step_choices, bounds):
    base = list(range(n))
    # build iset by applying removals via pop(index) and discard
    iset = IndexedSet(base)
    ref = list(iset)
    # apply removals
    for (kind, val) in ops:
        if kind == 'p':
            try:
                iset.pop(val)
            except IndexError:
                if -len(ref) <= val < len(ref): return ('unexpected IndexError', val, list(iset))
                return None
            if -len(ref) <= val < len(ref):
                exp = ref[val]; ref.pop(val)
                # can't easily verify returned due to possible mismatch, do below
            else: return None
        else:
            iset.discard(val)
            if val in ref: ref.remove(val)
    if list(iset) != ref: return ('list mismatch', list(iset), ref)
    # index checks
    for i in range(-len(ref)-3, len(ref)+3):
        try: got = iset[i]
        except IndexError: got = 'ISE'
        except Exception as e: got = type(e).__name__
        exp = ref[i] if -len(ref) <= i < len(ref) else 'ISE'
        if got != exp: return ('getitem', i, got, exp, list(iset))
    # pop on a copy each time
    for i in range(-len(ref)-3, len(ref)+3):
        a = IndexedSet(iset); b = list(ref)
        try: got = a.pop(i); gl = list(a)
        except IndexError: got = 'ISE'; gl = 'ISE'
        except Exception as e: got = type(e).__name__; gl='ERR'
        try:
            exp = b.pop(i); el = list(b)
        except IndexError: exp='ISE'; el='ISE'
        if got != exp or gl != el: return ('pop', i, got, gl, exp, el, list(ref))
    # slices
    fresh = IndexedSet(ref)
    for start in bounds:
        for stop in bounds:
            for step in step_choices:
                sl = slice(start, stop, step)
                g1 = list(iset[sl]); g2 = list(fresh[sl])
                e = ref[sl] if (step is None or step > 0) else None
                if g1 != g2: return ('slice fresh', sl, g1, g2, list(ref))
                if e is not None and g1 != e: return ('slice list', sl, g1, e, list(ref))
    return None

random.seed(0)
bounds = [None, -12, -9, -5, -1, 0, 1, 4, 8, 9, 12]
