import random, itertools
from boltons.setutils import IndexedSet

random.seed(42)
fails = []

def check(cond, msg):
    if not cond:
        fails.append(msg)

def raises(fn, exc):
    try:
        fn()
    except exc:
        return True
    except Exception:
        return False
    return False

# 1) random sequences of add/remove, then compare s[i], slices vs list(s) and fresh set
for trial in range(3000):
    n = random.randint(0, 30)
    items = random.sample(range(1000), n)
    s = IndexedSet(items)
    # random removals
    for _ in range(random.randint(0, n)):
        if not s:
            break
        victim = random.choice(list(s))
        s.remove(victim)
    L = list(s)
    fresh = IndexedSet(L)
    # in-range getitem
    for i in range(-len(L), len(L)):
        check(s[i] == L[i], f"getitem {i} on {L}: got {s[i]!r} want {L[i]!r}")
    # out-of-range getitem
    if L:
        check(raises(lambda: s[len(L)], IndexError), f"s[{len(L)}] should raise on {L}")
        check(raises(lambda: s[-len(L)-1], IndexError), f"s[-{len(L)+1}] should raise on {L}")
    else:
        check(raises(lambda: s[0], IndexError), "empty s[0]")
        check(raises(lambda: s[-1], IndexError), "empty s[-1]")
    # slices: all combinations
    rng = range(-len(L)-2, len(L)+3)
    for a in rng:
        for b in rng:
            for step in (1, 2, 3, -1, -2, -3):
                check(list(s[a:b:step]) == L[a:b:step],
                      f"slice [{a}:{b}:{step}] on {L}: got {list(s[a:b:step])} want {L[a:b:step]}")
                check(list(s[a:b:step]) == list(fresh[a:b:step]),
                      f"fresh slice mismatch {L} {a}:{b}:{step}")
    # pop comparisons (destructive): clone both, pop same index
    for i in list(range(-len(L)-1, len(L)+1)):
        s2 = IndexedSet(L); l2 = list(L)
        if i == -len(L)-1 or i == len(L):
            check(raises(lambda: s2.pop(i), IndexError), f"pop({i}) should raise on {L}")
            check(raises(lambda: l2.pop(i), IndexError), f"list pop({i}) raise on {L}")
            continue
        got = s2.pop(i)
        want = l2.pop(i)
        check(got == want and list(s2) == l2, f"pop({i}) on {L}: got {got!r}/{list(s2)} want {want!r}/{l2}")
    # pop() default
    if L:
        s2 = IndexedSet(L); l2 = list(L)
        check(s2.pop() == l2.pop() and list(s2) == l2, f"pop() on {L}")
    else:
        check(raises(lambda: IndexedSet().pop(), IndexError), "empty pop()")

print("fails:", len(fails))
for f in fails[:20]:
    print("  ", f)
