import random
from boltons.setutils import IndexedSet

random.seed(7)
fails = []

def check(cond, msg):
    if not cond:
        fails.append(msg)

def raises(fn, exc):
    try:
        fn()
    except exc:
        return True
    except Exception:
        return False
    return False

def expected_slice(L, a, b, step):
    # documented IndexedSet semantics: forward steps = list semantics;
    # negative step = reversed stream with forward bounds (negatives
    # normalized as max(len+n, 0))
    n = len(L)
    if step > 0:
        return L[a:b:step]
    rl = list(reversed(L))
    na = a if a >= 0 else max(n + a, 0)
    nb = b if b >= 0 else max(n + b, 0)
    return rl[na:nb:-step]

for trial in range(400):
    n = random.randint(0, 25)
    items = random.sample(range(1000), n)
    s = IndexedSet(items)
    for _ in range(random.randint(0, n)):
