    fresh = IndexedSet(L)
    for i in range(-len(L), len(L)):
        check(s[i] == L[i], f"getitem {i} on {L}: got {s[i]!r} want {L[i]!r}")
    rng = range(-len(L)-2, len(L)+3)
    for a in rng:
        for b in rng:
            for step in (1, 2, 3, -1, -2, -3):
                want = expected_slice(L, a, b, step)
                got = list(s[a:b:step])
                check(got == want, f"slice [{a}:{b}:{step}] on {L}: got {got} want {want}")
                check(got == list(fresh[a:b:step]), f"fresh mismatch {L} {a}:{b}:{step}")
