import itertools, random
from boltons.setutils import IndexedSet

fails = []

# A) exhaustive: for n=5, every ordered sequence of 'remove' and 'pop' ops
n = 5
base = list(range(n))
ops = [('r', x) for x in base] + [('p', i) for i in range(-n-1, n+1)]
# sample many random op sequences rather than full cross product of length<=4
random.seed(0)
for trial in range(20000):
    s = IndexedSet(base)
    k = random.randint(1, 6)
    seq = [random.choice(ops) for _ in range(k)]
    for kind, arg in seq:
        if not s:
            break
        try:
            if kind == 'r':
                if arg in s:
                    s.remove(arg)
            else:
                s.pop(arg)
        except IndexError:
            continue
        except TypeError:
            continue
        # after each op, invariants must hold
        L = list(s)
        fresh = IndexedSet(L)
        for i in range(-len(L), len(L)):
            if s[i] != L[i]:
                fails.append(f"getitem {i} state {L} after {seq[:seq.index((kind,arg))+1]} got {s[i]!r}")
        if len(L):
            try:
                s[len(L)]; fails.append(f"s[{len(L)}] no raise on {L}")
            except IndexError: pass
            try:
                s[-len(L)-1]; fails.append(f"s[-{len(L)+1}] no raise on {L}")
            except IndexError: pass
        for a in range(-len(L)-1, len(L)+2):
            for b in range(-len(L)-1, len(L)+2):
                for st in (1, -1, 2, -2):
                    g = list(s[a:b:st])
                    f = list(fresh[a:b:st])
                    if g != f:
                        fails.append(f"slice {a}:{b}:{st} state {L} got {g} want {f}")
        # also verify item_index_map values all valid
        for v in s.item_index_map.values():
            if not (0 <= v < len(s.item_list)):
                fails.append(f"map value {v} out of item_list range len={len(s.item_list)} state {L}")
            elif s.item_list[v] is s.item_list[v] and s.item_list[v] is None:
