from boltons.setutils import IndexedSet

def check_pop(idx_setup, idx, label):
    s = idx_setup()
    n_before = len(s)
    ref = list(s)
    try:
        got = s.pop(idx)
        # determine expected semantics: pop(idx) should equal ref[idx] if in range else IndexError
        if -n_before <= idx < n_before:
            expected = ref[idx]
            ok = got == expected
            # verify remaining matches list-with-that-element-removed
            exp_remaining = ref.copy(); del exp_remaining[idx]
            ok = ok and list(s) == exp_remaining
            print(f"{label}: popped {got!r} (expected {expected!r}) remaining_ok={list(s)==exp_remaining} {'OK' if ok else 'WRONG'}")
        else:
            print(f"{label}: popped {got!r} <-- SHOULD RAISE IndexError (idx={idx}, len={n_before})")
    except IndexError:
        if -n_before <= idx < n_before:
            print(f"{label}: raised IndexError <-- SHOULD HAVE POPPED (idx={idx}, len={n_before})")
