from humanize.number import metric

prefix = {}
for i,c in enumerate("kMGTPEZYRQ"): prefix[c] = 3*(i+1)
for i,c in enumerate("mμnpfazyrq"): prefix[c] = -3*(i+1)

def implied(s, unit):
    m = re.match(r'^(-?\d+(?:\.\d+)?)(?:([kMGTPEZYRQmμnpfazyrq]))?(.*)$', s)
    if not m: return None
    num, p, u = m.groups()
    if u != unit: return None
    v = float(num)
    if p: v *= 10**prefix[p]
    return v

def sigdigits(s):
    num = re.match(r'^(-?\d+\.?\d*)', s).group(1).replace('-','').replace('.','')
    return len(num.lstrip('0'))

def round_sig(x, p):
    if x == 0: return 0.0
    return round(x, p - 1 - math.floor(math.log10(abs(x))))

mantissas = [9.995, 9.996, 9.999, 9.9995, 9.9999, 1.0, 1.005, 9.95, 9.96,
             99.96, 99.995, 999.6, 999.5, 999.95, 999.999, 9.94999, 0.99995,
             9.9996, 1.0005, 99.999, 1.005, 9.9949]
problems = []
for p in [1,2,3,4,5]:
