const SemVer = require('./classes/semver')
const { compareIdentifiers } = require('./internal/identifiers')

// replicate case 'pre' with a switch for old vs new matching logic
function incPre(ver, identifier, identifierBase, useNew) {
  const s = new SemVer(ver)
  const base = Number(identifierBase) ? 1 : 0
  if (s.prerelease.length === 0) {
    s.prerelease = [base]
  } else {
    let i = s.prerelease.length
    while (--i >= 0) {
      if (typeof s.prerelease[i] === 'number') { s.prerelease[i]++; i = -2 }
    }
    if (i === -1) {
      if (identifier === s.prerelease.join('.') && identifierBase === false) {
        return 'THROW'
      }
      s.prerelease.push(base)
    }
  }
  if (identifier) {
    let prerelease = [identifier, base]
    if (identifierBase === false) prerelease = [identifier]
    let matched
    if (useNew) {
      const idParts = identifier.split('.')
      const m = idParts.every((part, idx) => compareIdentifiers(s.prerelease[idx], part) === 0)
      if (m && !isNaN(s.prerelease[idParts.length])) { matched = true } else { s.prerelease = prerelease; matched = false }
    } else {
      // old logic: compare only segment 0 against whole identifier
      const m = compareIdentifiers(s.prerelease[0], identifier) === 0
      if (m && !isNaN(s.prerelease[1])) { matched = true } else { s.prerelease = prerelease; matched = false }
    }
  }
  s.raw = s.format()
  return s.version
}

const versions = ['1.0.0','1.0.0-0','1.0.0-a','1.0.0-a.1','1.0.0-a.2','1.0.0-rc.next','1.0.0-rc.next.3','1.0.0-rc.next.0','1.0.0-rc.next.beta','1.0.0-rc.next.3.4','1.0.0-alpha.1.1a.3','1.0.0-a.1.2','1.0.0-0.1.5','1.0.0-1.2.3','1.0.0-x.rc.next.3','1.0.0-a.01.3']
const ids = [undefined,'a','dev','rc.next','a.1','alpha.1.1a','0.1','1.2','rc.next.3','a.1.2','dev.baz']
const bases = [undefined,'0','1',false]
let divs = 0, checked = 0
for (const v of versions) for (const id of ids) for (const b of bases) {
  checked++
  let o, n
  try { o = incPre(v, id, b, false) } catch (e) { o = 'ERR' }
  try { n = incPre(v, id, b, true) } catch (e) { n = 'ERR' }
  if (o !== n) { divs++; console.log('DIVERGE |', v, '| id=', JSON.stringify(id), '| base=', JSON.stringify(b), '| old=', o, '| new=', n) }
}
console.log('checked', checked, 'divergences', divs)
"

