function load (which) {
  // swap the file in place is unsafe; instead load by absolute path with a fresh require cache per variant
  const file = path.join(base, 'range.js')
  const fs = require('fs')
  const saved = fs.readFileSync(file, 'utf8')
  const variant = fs.readFileSync(path.join(__dirname, which === 'pre' ? 'range.prefix.js' : 'range.orig.js'), 'utf8')
  fs.writeFileSync(file, variant)
  for (const k of Object.keys(require.cache)) delete require.cache[k]
  const Range = require(file)
  const subset = require(path.join(__dirname, '..', 'ranges', 'subset.js'))
  fs.writeFileSync(file, saved)
  return { Range, subset }
}
