// consumed: it stays available to the next, more right-ward candidate match,
// and no identifier can be cut short by it.  Consuming it lets the engine
// give up the non-digit tail character, which turns '2.3.1-nightly.7f3c' into
// '2.3.1-nightly.7' and '1.2.3-rc.5' into '1.2.3-rc'.
createToken('COERCEFULL', src[t.COERCEPLAIN] +
              `(?:${src[t.PRERELEASE]})?` +
              `(?:${src[t.BUILD]})?` +
              `(?=${src[t.COERCETAIL]})`)
"""
